CREATE OR REPLACE FUNCTION public.task_file_access(_name text, _uid uuid, _write boolean) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF split_part(_name,'/',1) !~ '^[0-9a-fA-F-]{36}$' THEN RETURN false; END IF; tid:=split_part(_name,'/',1)::uuid; IF _write THEN RETURN (public.task_manage(tid,_uid) OR public.task_execute(tid,_uid)) AND EXISTS(SELECT 1 FROM tasks t JOIN feature_flags f ON f.key=CASE WHEN t.kind='official' THEN 'tarefas' ELSE 'voluntarias' END WHERE t.id=tid AND f.enabled); END IF; RETURN public.task_visible(tid,_uid); EXCEPTION WHEN invalid_text_representation THEN RETURN false; END $$;
REVOKE ALL ON FUNCTION public.task_file_access(text,uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.task_file_access(text,uuid,boolean) TO authenticated;
CREATE POLICY task_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='task-files' AND public.task_file_access(name,auth.uid(),false));
CREATE POLICY task_files_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='task-files' AND public.task_file_access(name,auth.uid(),true));